<?php
declare(strict_types=1);
namespace App\Repositories;
use App\Core\Database;
final class AttendanceRepository{
public function __construct(private readonly Database $db){}
public function students(int$class,string$date,int$institute):array{return$this->db->query("SELECT s.id,s.registration_no,s.student_name,COALESCE(a.status,'Present') attendance_status,COALESCE(a.remarks,'') remarks FROM students s LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date=:d WHERE s.class_id=:c AND s.institute_id=:i AND s.status='active' ORDER BY s.student_name",['d'=>$date,'c'=>$class,'i'=>$institute])->fetchAll();}
public function employees(string$date,int$institute):array{return$this->db->query("SELECT e.id,e.employee_no,e.name,e.role,COALESCE(a.status,'Present') attendance_status,a.time_in,a.time_out,COALESCE(a.remarks,'') remarks FROM employees e LEFT JOIN employee_attendance a ON a.employee_id=e.id AND a.attendance_date=:d WHERE e.institute_id=:i AND e.status='active' ORDER BY e.name",['d'=>$date,'i'=>$institute])->fetchAll();}
public function studentRecords(int$institute,string$from,string$to,int$class=0):array{$where=$class?' AND s.class_id=:class':'';$params=['institute'=>$institute,'from'=>$from,'to'=>$to];if($class)$params['class']=$class;return$this->db->query("SELECT a.attendance_date,s.registration_no,s.student_name,c.name class_name,a.status,a.remarks FROM student_attendance a JOIN students s ON s.id=a.student_id LEFT JOIN classes c ON c.id=s.class_id WHERE s.institute_id=:institute AND a.attendance_date BETWEEN :from AND :to{$where} ORDER BY a.attendance_date DESC,s.student_name",$params)->fetchAll();}
public function employeeRecords(int$institute,string$from,string$to):array{return$this->db->query("SELECT a.attendance_date,e.employee_no,e.name,e.role,a.status,a.time_in,a.time_out,a.remarks FROM employee_attendance a JOIN employees e ON e.id=a.employee_id WHERE e.institute_id=:institute AND a.attendance_date BETWEEN :from AND :to ORDER BY a.attendance_date DESC,e.name",['institute'=>$institute,'from'=>$from,'to'=>$to])->fetchAll();}
public function classSummary(int$institute,string$date,int$class=0):array{$where=$class?' AND c.id=:class':'';$p=['i'=>$institute,'d'=>$date];if($class)$p['class']=$class;return$this->db->query("SELECT c.id,c.name,COUNT(a.id) marked,SUM(a.status='Present') present_count,SUM(a.status='Absent') absent_count,SUM(a.status='Leave') leave_count FROM classes c LEFT JOIN students s ON s.class_id=c.id AND s.status='active' LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date=:d WHERE c.institute_id=:i{$where} GROUP BY c.id,c.name ORDER BY c.name",$p)->fetchAll();}
public function saveStudents(string$date,array$rows,int$user):void{$sql="INSERT INTO student_attendance(student_id,attendance_date,status,remarks,marked_by,created_at,updated_at) VALUES (:id,:date,:status,:remarks,:user,:created,:updated) ON DUPLICATE KEY UPDATE status=VALUES(status),remarks=VALUES(remarks),marked_by=VALUES(marked_by),updated_at=VALUES(updated_at)";$now=date('Y-m-d H:i:s');foreach($rows as$r)$this->db->query($sql,$r+['date'=>$date,'user'=>$user,'created'=>$now,'updated'=>$now]);}
public function saveEmployees(string$date,array$rows,int$user):void{$sql="INSERT INTO employee_attendance(employee_id,attendance_date,status,time_in,time_out,remarks,marked_by,created_at,updated_at) VALUES (:id,:date,:status,:time_in,:time_out,:remarks,:user,:created,:updated) ON DUPLICATE KEY UPDATE status=VALUES(status),time_in=VALUES(time_in),time_out=VALUES(time_out),remarks=VALUES(remarks),marked_by=VALUES(marked_by),updated_at=VALUES(updated_at)";$now=date('Y-m-d H:i:s');foreach($rows as$r)$this->db->query($sql,$r+['date'=>$date,'user'=>$user,'created'=>$now,'updated'=>$now]);}
public function db():Database{return$this->db;}
}
